// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
        }
        vm.assume(v > 0);
        vm.assume(caddress != address(0));
        vm.assume(from != address(0));

        // Deploy a helper that always succeeds on the low-level call
        SuccessHelper helper = new SuccessHelper();
        address successCallee = address(helper);
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        // Pre-encode the call data to check if the callee would accept the selector
        // The helper exposes a public mapping to check if transferFrom was called
        bool ret = c.transfer(from, successCallee, _tos, v);
        // The reference returns true, mutant returns false when the call succeeds
        assertTrue(ret);
    }
}

contract SuccessHelper {
    mapping(bytes32 => bool) public called;
    function transferFrom(address,address,uint256) external returns (bool) {
        return true;
    }
}
